    "glossaryVersion": "calr-terms-2026-10-v2",
    "completenessNote": "逐条对译，共 7 条；条号与官方原文一一对应，未合并、未省略。",
    "articles": [
      {
        "no": 1,
        "text": {
          "en": "These Provisions are formulated in accordance with Articles 117 and 211 of the Maritime Code of the People's Republic of China."
        },
        "noLabel": {
          "en": "Article 1."
        }
      },
      {
        "no": 2,
        "text": {
          "en": "These Provisions apply to maritime carriage of passengers between ports of the People's Republic of China."
        },
        "noLabel": {
          "en": "Article 2."
        }
      },
      {
        "no": 3,
        "text": {
          "en": "The limits of liability of the carrier in each maritime carriage of passengers shall be as follows:\n(a) for personal injury or death of a passenger, not more than RMB 40,000 per passenger;\n(b) for loss of or damage to the baggage carried by a passenger, not more than RMB 800 per passenger;\n(c) for loss of or damage to a passenger's vehicle, including the baggage carried in that vehicle, not more than RMB 3,200 per vehicle;\n(d) for loss of or damage to passengers' other baggage not covered by subparagraphs (b) and (c) of this paragraph, not more than RMB 20 per kilogram.\nThe carrier and the passenger may agree in writing on limits of liability higher than those prescribed in paragraph 1 of this Article."
        },
        "noLabel": {
          "en": "Article 3."
        }
      },
      {
        "no": 4,
        "text": {
          "en": "The limitation of liability for personal injury or death of passengers in maritime carriage of passengers shall be calculated by multiplying RMB 40,000 by the passenger capacity specified in the ship's certificate, but the maximum shall not exceed RMB 21 million."
        },
        "noLabel": {
          "en": "Article 4."
        }
      },
      {
        "no": 5,
        "text": {
          "en": "Compensation paid to foreign passengers, overseas Chinese and passengers who are compatriots from Hong Kong, China, Macao, China or Taiwan, China may be converted into the currency of the relevant foreign country or region. The exchange rate shall be determined at the foreign exchange rate published by the foreign exchange administration department of the People's Republic of China on the date of payment of the compensation."
        },
        "noLabel": {
          "en": "Article 5."
        }
      },
      {
        "no": 6,
        "text": {
          "en": "These Provisions shall be interpreted by the Ministry of Communications of the People's Republic of China."
        },
        "noLabel": {
          "en": "Article 6."
        }
      },
      {
        "no": 7,
        "text": {
          "en": "These Provisions shall come into force on 1 January 1994."
        },
        "noLabel": {
          "en": "Article 7."
        }
      }
    ]
